{
  "technical_and_design_decisions": [
    "Use Spring XD module architecture (source/processor/sink) on Java 17+ and Spring Framework 6.0.",
    "For Kafka source, use the low-level Kafka consumer API with manual partition assignment and explicit offset control as requested in U2.",
    "For mass ingestion (U1), leverage Spring Batch chunk processing with JDBC paging for sources and bulk COPY (via JDBC) for HAWQ/GPDB sinks to maximize throughput.",
    "Custom module installation (U3) extends the existing Admin REST API with a multipart endpoint that stores the uber-jar in the module repository and triggers registration.",
    "Generator source (U5) spawns configurable worker threads that emit byte-array payloads of specified size; perf-meter sink (U6) maintains a message counter and logs aggregated rate metrics to the container log.",
    "Sample application (U4) is delivered as a separate GitHub repository with docker-compose and scripts, not integrated into core codebase.",
    "All modules are built as standard Spring XD module packages compatible with the singlenode container."
  ],
  "assumptions": [
    "Base Spring XD platform (container, module lifecycle, singlenode, REST API scaffolding) already exists and is functional.",
    "Existing JDBC source and HDFS sink modules are available; this increment enhances them and adds HAWQ/GPDB sink.",
    "A Kafka broker and Zookeeper are available in dev/test environments for spike, implementation, and CI.",
    "CI pipeline (e.g., Jenkins) exists; we only add test code and configuration to plug into it.",
    "Scope of 'mass ingest from databases (and others)' is limited to relational databases as sources and HDFS/HAWQ/GPDB as destinations; other sources are out of scope.",
    "Effort estimates cover a single developer's implementation, unit/integration testing, and basic docs; they exclude separate QA, UI design, production deployment, and project management.",
    "Uber-jar custom modules follow the expected Spring XD module structure and manifest conventions."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Kafka simple consumer API spike",
      "activity_description": "Research Kafka low-level consumer API, prototype offset and partition control, document findings and approach (U2).",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A2",
      "activity_name": "Implement Kafka source module",
      "activity_description": "Develop Spring XD source module using simple consumer API with manual offset and partition assignment (U2).",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A3",
      "activity_name": "Implement Kafka sink module",
      "activity_description": "Develop Spring XD sink module using Kafka producer for ingestion to Kafka (supports U4, U8).",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A4.1",
      "activity_name": "Database source for mass ingestion",
      "activity_description": "Implement/enhance JDBC-based source module with batch reading and pagination for efficient mass ingestion (U1).",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A4.2",
      "activity_name": "HAWQ/GPDB sink module",
      "activity_description": "Implement bulk sink module for HAWQ/Greenplum using JDBC/COPY for efficient loading (U1).",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A4.3",
      "activity_name": "Mass ingestion pipeline optimization",
      "activity_description": "Configure and optimize batch ingestion flows (DB->HDFS/HAWQ/GPDB) for throughput, incl. HDFS sink tuning (U1).",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A5",
      "activity_name": "REST API for custom module upload",
      "activity_description": "Extend admin REST API to accept uber-jar module upload, store and register in cluster (U3).",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A6",
      "activity_name": "Generator source module",
      "activity_description": "Implement generator source that emits N messages of given size with configurable threads (U5).",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A7",
      "activity_name": "Perf-meter sink module",
      "activity_description": "Implement perf-meter sink that logs timestamp, count, and rate every N messages (U6).",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A8",
      "activity_name": "Sample GitHub project for Kafka",
      "activity_description": "Create reference app repo with provisioning scripts/compose for Spring XD + Kafka as bus/source (U4).",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A9",
      "activity_name": "Stream definition and performance validation",
      "activity_description": "Define generator | perf-meter stream, run in singlenode, validate 1M msgs perf (U7).",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A10",
      "activity_name": "Kafka module test coverage and CI",
      "activity_description": "Write unit/integration tests for Kafka source and sink, integrate into CI build (U8).",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A11",
      "activity_name": "Documentation and integration",
      "activity_description": "Overall README, module docs, build scripts, and final integration of increment.",
      "most_likely_effort": 16
    }
  ],
  "reported_total": {
    "most_likely_effort": 304
  }
}

